import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.CqGS6Fr9.js";const u=JSON.parse('{"title":"Managing modpacks","description":"","frontmatter":{"pageId":"admins/modpacks","contentRevision":2},"headers":[],"relativePath":"en/admins/modpacks.md","filePath":"en/admins/modpacks.md"}'),o={name:"en/admins/modpacks.md"};function s(n,e,l,d,c,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="managing-modpacks" tabindex="-1">Managing modpacks <a class="header-anchor" href="#managing-modpacks" aria-label="Permalink to &quot;Managing modpacks&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol><li>Prepare a tested set in a separate game installation. Record ModsConfig.xml, load order, versions and hashes.</li><li>Run modpack import --from &lt;ModsConfig.xml&gt; --mods-dir &lt;folders&gt; --dry-run. After review, add --server/--token to upload requirements.</li><li>modpack defs collects permitted ThingDef/PawnKindDef names; an empty list disables that check. Import shared settings only for selected --mod entries loading below Rimlink.</li><li>For server delivery, run modpack package requirements --output &lt;new-file&gt;, then package pack --source &lt;redistributable-folders&gt; --requirements &lt;file&gt; --output &lt;new-directory&gt;.</li><li>Review archive.zip, manifest.json, licenses and settings. package publish --from &lt;directory&gt; requires --confirm-redistribution; --confirm-public and --confirm-shared-settings acknowledge those disclosures. Inspect package status; unpublish removes publication.</li></ol><p>Test a clean client after changing the collection.</p><h2 id="modpack-release" tabindex="-1">Treat the collection as a release <a class="header-anchor" href="#modpack-release" aria-label="Permalink to &quot;Treat the collection as a release {#modpack-release}&quot;">​</a></h2><p>Test the collection on a separate client first. Import --dry-run previews requirements; upload only after review. Supply Steam/local/Workshop roots so hashes/versions match loaded files. Import shared settings only for selected mods: they can contain personal paths or secrets.</p><p>Requirements and a delivery ZIP are distinct. Changing requirements can invalidate an older ZIP. Rebuild from redistributable source folders, review manifest/archive and settings consent separately. Do not include Core/DLC or game files.</p><h2 id="delivery-accept" tabindex="-1">Accept a new collection and withdraw publication <a class="header-anchor" href="#delivery-accept" aria-label="Permalink to &quot;Accept a new collection and withdraw publication {#delivery-accept}&quot;">​</a></h2><p>On a clean test client verify diff → download → verification → consent → restart → login. Separately test an unmanaged conflicting copy and refusal without overwrite. This does not authorize deleting the user&#39;s Mods folder.</p><p>Unpublish removes availability; it does not automatically revert installed clients or imported requirements. Retain earlier requirements, package source and settings for coordinated rollback. A DataDir backup does not replace preservation of source mods/licenses and external delivery roots.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not package the game directory, Core/DLC or mod secrets. Pack requires the complete prepared collection and a new output directory. Publishing is a separate external operator action. Requirement changes may invalidate a previously published package.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./cli">CLI reference</a></li><li><a href="./../players/modpacks">Server modpacks</a></li><li><a href="./updating">Updating server and clients</a></li></ul>',15)])])}const h=a(o,[["render",s]]);export{u as __pageData,h as default};
